/* From Uiverse.io by YaroslavFilipenko - Tags: slider, input, toggle switch */
.__UIV_SCOPE__ .switch {
  position: relative;
  display: inline-block;
  width: 60px;
  height: 20px;
}

.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #b1b9c3;
  -webkit-transition: 0.4s;
  transition: 0.4s;
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: '';
  height: 30px;
  width: 30px;
  bottom: -5px;
  background: #18333E;
  -webkit-transition: 0.4s;
  transition: 0.4s;
}

.__UIV_SCOPE__ .slider.round {
  border-radius: 34px;
}

.__UIV_SCOPE__ .slider.round:before {
  border-radius: 50%;
}

.__UIV_SCOPE__ input:checked+.slider {
  background-color: #b1b9c3;
}

.__UIV_SCOPE__ input:checked+.slider:before {
  -webkit-transform: translateX(35px);
  -ms-transform: translateX(35px);
  transform: translateX(35px);
  background: #F2F8FD;
}
